# ── Anthropic ────────────────────────────────────────────────────────────────
class AnthropicProvider(Provider):
    name = "anthropic"

    def __init__(self):
        self._client = None

    def available(self) -> bool:
        if not os.getenv("ANTHROPIC_API_KEY"):
            return False
        try:
            import anthropic  # noqa: F401
        except ImportError:
            return False
        return True

    def _get_client(self):
        if self._client is None:
            import anthropic

            self._client = anthropic.Anthropic()
        return self._client

    def complete(self, *, model, system, messages, json_schema=None, max_tokens=4000):
        client = self._get_client()
        kwargs: Dict[str, Any] = dict(
            model=model,
            max_tokens=max_tokens,
            system=system,
            messages=messages,
            thinking={"type": "adaptive"},
        )
        if json_schema is not None:
            kwargs["output_config"] = {
                "format": {"type": "json_schema", "schema": json_schema}
            }
        resp = client.messages.create(**kwargs)
        text = "".join(b.text for b in resp.content if b.type == "text")
        usage = {
            "input_tokens": getattr(resp.usage, "input_tokens", None),
            "output_tokens": getattr(resp.usage, "output_tokens", None),
        }
        return LLMResult(
            provider=self.name,
            model=model,
            text=text,
            parsed=parse_json(text) if json_schema is not None else None,
            usage=usage,
        )


# ── OpenAI ───────────────────────────────────────────────────────────────────
class OpenAIProvider(Provider):
    name = "openai"

    def __init__(self):
        self._client = None

    def available(self) -> bool:
        if not os.getenv("OPENAI_API_KEY"):
            return False
        try:
            import openai  # noqa: F401
        except ImportError:
            return False
        return True

    def _get_client(self):
        if self._client is None:
            from openai import OpenAI

            self._client = OpenAI()
        return self._client

    def complete(self, *, model, system, messages, json_schema=None, max_tokens=4000):
        client = self._get_client()
        sys = system
        if json_schema is not None:
            sys = system + _schema_instruction(json_schema)
        oai_messages = [{"role": "system", "content": sys}] + messages
        kwargs: Dict[str, Any] = dict(
            model=model,
            messages=oai_messages,
            max_tokens=max_tokens,
        )
        if json_schema is not None:
            kwargs["response_format"] = {"type": "json_object"}
        resp = client.chat.completions.create(**kwargs)
        text = resp.choices[0].message.content or ""
        usage = {}
        if getattr(resp, "usage", None):
            usage = {
                "input_tokens": resp.usage.prompt_tokens,
                "output_tokens": resp.usage.completion_tokens,
            }
        return LLMResult(
            provider=self.name,
            model=model,
            text=text,
            parsed=parse_json(text) if json_schema is not None else None,
            usage=usage,
        )


# ── Google ───────────────────────────────────────────────────────────────────
class GoogleProvider(Provider):
    name = "google"

    def __init__(self):
        self._client = None

    def available(self) -> bool:
        if not os.getenv("GOOGLE_API_KEY"):
            return False
        try:
            from google import genai  # noqa: F401
        except ImportError:
            return False
        return True

    def _get_client(self):
        if self._client is None:
            from google import genai

            self._client = genai.Client()
        return self._client

    def complete(self, *, model, system, messages, json_schema=None, max_tokens=4000):
        from google.genai import types

        client = self._get_client()
        sys = system
        if json_schema is not None:
            sys = system + _schema_instruction(json_schema)

        contents = []
        for m in messages:
            role = "model" if m["role"] == "assistant" else "user"
            contents.append(
                types.Content(role=role, parts=[types.Part(text=m["content"])])
            )

        config = types.GenerateContentConfig(
            system_instruction=sys,
            max_output_tokens=max_tokens,
            response_mime_type="application/json" if json_schema is not None else None,
        )
        resp = client.models.generate_content(
            model=model, contents=contents, config=config
        )
        text = resp.text or ""
        usage = {}
        meta = getattr(resp, "usage_metadata", None)
        if meta is not None:
            usage = {
                "input_tokens": getattr(meta, "prompt_token_count", None),
                "output_tokens": getattr(meta, "candidates_token_count", None),
            }
        return LLMResult(
            provider=self.name,
            model=model,
            text=text,
            parsed=parse_json(text) if json_schema is not None else None,
            usage=usage,
        )


_REGISTRY = {
    "anthropic": AnthropicProvider,
    "openai": OpenAIProvider,
    "google": GoogleProvider,
}


def get_provider(name: str) -> Provider:
    if name not in _REGISTRY:
        raise ProviderError(
            f"Unknown provider '{name}'. Known: {sorted(_REGISTRY)}"
        )
    return _REGISTRY[name]()


def provider_status() -> Dict[str, bool]:
    """Which providers are usable right now (SDK installed + key present)."""
    return {name: cls().available() for name, cls in _REGISTRY.items()}
